-- Preflight 254 (solo lectura, UNA consulta): control | observado | esperado | estado.
-- Estados: OK = listo para aplicar · YA APLICADA = la 254 ya está (reaplicar es idempotente) · REVISAR = la definición NO es la auditada
-- (cambio ajeno: NO aplicar la 254 hasta entenderlo; la migración también abortaría) · BLOQUEA = falta algo requerido.
select * from (
  select 1 as n, 'tablas armado_paquetes y tarifario_resultado existen' as control,
         (to_regclass('public.armado_paquetes') is not null and to_regclass('public.tarifario_resultado') is not null)::text as observado, 'true' as esperado,
         case when to_regclass('public.armado_paquetes') is not null and to_regclass('public.tarifario_resultado') is not null then 'OK' else 'BLOQUEA' end as estado
  union all
  select 2, 'huella función tarifario_trg_bump_armado_paquetes', coalesce(md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.tarifario_trg_bump_armado_paquetes()')), chr(13), '')),'no existe'), '181: 368cb5199877e9cfbc10f66c6e74d113 | 254: 47a597c5ac1faaf86c9820797115bd61', case when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.tarifario_trg_bump_armado_paquetes()')), chr(13), '')) is null then 'BLOQUEA' when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.tarifario_trg_bump_armado_paquetes()')), chr(13), '')) = '368cb5199877e9cfbc10f66c6e74d113' then 'OK' when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.tarifario_trg_bump_armado_paquetes()')), chr(13), '')) = '47a597c5ac1faaf86c9820797115bd61' then 'YA APLICADA' else 'REVISAR' end
  union all
  select 3, 'huella definición del trigger tarifario_trg_armado_paquetes', coalesce((select md5(pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgname = 'tarifario_trg_armado_paquetes' and t.tgrelid = to_regclass('public.armado_paquetes')),'no existe'), '181: d6c23513669a2addf5b7fbfa67f20d62 | 254: 65c829bcdf7f83da9d2f7f6c54fbb122', case when (select md5(pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgname = 'tarifario_trg_armado_paquetes' and t.tgrelid = to_regclass('public.armado_paquetes')) is null then 'BLOQUEA' when (select md5(pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgname = 'tarifario_trg_armado_paquetes' and t.tgrelid = to_regclass('public.armado_paquetes')) = 'd6c23513669a2addf5b7fbfa67f20d62' then 'OK' when (select md5(pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgname = 'tarifario_trg_armado_paquetes' and t.tgrelid = to_regclass('public.armado_paquetes')) = '65c829bcdf7f83da9d2f7f6c54fbb122' then 'YA APLICADA' else 'REVISAR' end
  union all
  select 4, 'huella publicar_tarifario_resultado_interno', coalesce(md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.publicar_tarifario_resultado_interno(bigint,bigint,bigint,text,jsonb)')), chr(13), '')),'no existe'), '234: c0a7d986441e22a74b2fcd20b505706f | 254: 990e246824e567293372355d290a61a9', case when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.publicar_tarifario_resultado_interno(bigint,bigint,bigint,text,jsonb)')), chr(13), '')) is null then 'BLOQUEA' when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.publicar_tarifario_resultado_interno(bigint,bigint,bigint,text,jsonb)')), chr(13), '')) = 'c0a7d986441e22a74b2fcd20b505706f' then 'OK' when md5(replace((select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.publicar_tarifario_resultado_interno(bigint,bigint,bigint,text,jsonb)')), chr(13), '')) = '990e246824e567293372355d290a61a9' then 'YA APLICADA' else 'REVISAR' end
  union all
  select 5, 'huella vista tarifario_resultado_publicable', coalesce((select md5(pg_get_viewdef(to_regclass('public.tarifario_resultado_publicable'), true))),'no existe'), '226: 41b2f693d2a480abe615f57403294375 | 254: d4165ca9aaa100ae9bfb49d07e1aacb6', case when (select md5(pg_get_viewdef(to_regclass('public.tarifario_resultado_publicable'), true))) is null then 'BLOQUEA' when (select md5(pg_get_viewdef(to_regclass('public.tarifario_resultado_publicable'), true))) = '41b2f693d2a480abe615f57403294375' then 'OK' when (select md5(pg_get_viewdef(to_regclass('public.tarifario_resultado_publicable'), true))) = 'd4165ca9aaa100ae9bfb49d07e1aacb6' then 'YA APLICADA' else 'REVISAR' end
  union all
  select 6, 'columnas nuevas ya presentes (pvp_infante_fijo + 2 sin_fijo)',
         ((select count(*) from information_schema.columns where table_schema='public' and ((table_name='armado_paquetes' and column_name='pvp_infante_fijo') or (table_name='tarifario_resultado' and column_name in ('precio_pvp_sin_fijo','precio_pvp_menor2_sin_fijo')))))::text, '0 (aplicar) o 3 (ya aplicada)', 'INFO'
) t order by n;
